            dtypes[low] = dtypes[high];
            dtypes[high] = tmp;
        }
        else if (res == dtypes[low]) {
            /* `dtypes[high]` cannot influence result: clear */
            dtypes[high] = NULL;
        }
    }

    if (length == 2) {
        return res;
    }
    Py_DECREF(res);
    return reduce_dtypes_to_most_knowledgeable(length - half, dtypes);
}

PyArray_PromoteDTypeSequence(
