    Py_DECREF(common_dtype);
    npy_free_workspace(workspace);
    return result;

  error:
    Py_XDECREF(result);
    Py_XDECREF(common_dtype);
    npy_free_workspace(workspace);
    return NULL;
}

PyArray_GetCastingImpl(PyArray_DTypeMeta *from, PyArray_DTypeMeta *to)
{
    PyObject *res = NULL;
    if (from == to) {
        if ((NPY_DT_SLOTS(from)->within_dtype_castingimpl) != NULL) {
