        if (flags & NPY_ARRAY_WAS_PYTHON_COMPLEX) {
            return ((casting == NPY_UNSAFE_CASTING) || ((casting & NPY_SAME_VALUE_CASTING_FLAG) > 0));
        }
        return 1;
